// Java Lab · native Scriptable widget. Tokens remain in iPhone Keychain.
/* One calendar for the site and Scriptable. Dates are in Asia/Barnaul. */
(function(root){
  const DAY=86400000;
  const iso=t=>new Date(t).toISOString().slice(0,10);
  const time=s=>Date.parse(s+'T00:00:00Z');
  const dow=t=>(new Date(t).getUTCDay()+6)%7;
  const planned=t=>[0,2,4].includes(dow(t));
  function date(now=new Date()){return iso(now.getTime()+7*3600000);}
  function slot(t){while(!planned(t))t-=DAY;return t;}
  function stats(state,today=date()){
    const current=time(today),monday=current-dow(current)*DAY;
    const sessions=(state.sessions||[]).filter(s=>/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&Number.isFinite(time(s.date))&&iso(time(s.date))===s.date&&s.date<=today);
    const completed=new Set(sessions.filter(s=>s.kind==='complete'||(!s.kind&&state.entries?.[s.lesson]?.completedOn===s.date&&state.entries[s.lesson].done)).map(s=>s.date));
    const slots=new Set([...completed].map(d=>iso(slot(time(d)))));
    const latest=slot(current),isStudy=planned(current),done=slots.has(iso(latest));
    const active=done,mode=done?(isStudy?'lit':'rest'):(isStudy?'waiting':'idle');
    let cursor=isStudy&&!done?slot(current-DAY):latest;
    const last=cursor;let chain=0;
    while(slots.has(iso(cursor))){chain++;cursor=slot(cursor-DAY);}
    const earliest=chain?slot(cursor+DAY):Infinity;
    const streak=chain?[...completed].filter(d=>{const t=slot(time(d));return t>=earliest&&t<=last;}).length:0;
    const tier=streak>=60?'aurora':streak>=30?'ruby':'amber';
    const milestone=streak<30?30:streak<60?60:Math.floor(streak/30+1)*30;
    let next=current+(isStudy&&!done?0:DAY);while(!planned(next))next+=DAY;
    const days=Array.from({length:7},(_,i)=>{const t=monday+i*DAY;return {date:iso(t),planned:planned(t),done:slots.has(iso(t)),activity:sessions.some(s=>s.date===iso(t)),future:t>current};});
    const count=days.filter(d=>d.planned&&d.done).length;
    const activity={};for(const s of sessions){(activity[s.date]??=new Set()).add(s.lesson);}
    return {today,mode,active,isStudy,done,count,streak,tier,milestone,next:iso(next),days,completedDays:completed.size,
      title:mode==='lit'?'Сегодня получилось!':mode==='rest'?'Сегодня отдых':mode==='waiting'?'Твой учебный день':'Отдых. Начнём спокойно',
      hint:mode==='lit'?'Огонёк зажжён. Хорошая работа.':mode==='rest'?'Огонёк с тобой. Можно выдохнуть.':mode==='waiting'?'Заверши один урок — зажги огонёк.':'Огонёк зажжётся после завершённого урока.',
      activity:Object.fromEntries(Object.entries(activity).map(([k,v])=>[k,v.size]))};
  }
  const api={stats,date,DAY};root.LabRhythm=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);

/* Native Scriptable layout. The five PNGs are compiled from original vectors. */
(function(root){
 function tier(days){return days<=0?'neutral':days<=30?'amber':days<=60?'ruby':days<=90?'magenta':'lilac';}
 function caption(days){const n=days%100,last=days%10;return (n>=11&&n<=14?'дней':last===1?'день':last>=2&&last<=4?'дня':'дней')+' подряд';}
 function layout(medium=false,compact=false){return medium?{padding:12,header:18,flame:88,font:42,label:10}:compact?{padding:9,header:17,flame:48,font:32,label:9}:{padding:10,header:18,flame:56,font:36,label:10};}
 function nativeFallback(name,colour){
  const bg=name.startsWith('background'),logo=name==='logo';
  const width=name==='background-medium'?1024:512;
  const ctx=new DrawContext();ctx.size=new Size(bg?width:logo?64:160,bg?512:logo?80:160);ctx.opaque=bg;ctx.respectScreenScale=false;
  if(bg){ctx.setFillColor(new Color('fbfcf5'));ctx.fillRect(new Rect(0,0,width,512));ctx.setFillColor(new Color('9cbb91',.23));ctx.fillEllipse(new Rect(width-122,-130,220,330));ctx.setFillColor(new Color('acc799',.24));ctx.fillEllipse(new Rect(-155,315,350,300));return ctx.getImage();}
  const path=new Path();
  if(logo){path.move(new Point(38,26));path.addLine(new Point(58,26));path.addLine(new Point(58,48));path.addCurve(new Point(5,63),new Point(58,84),new Point(20,86));path.addLine(new Point(18,53));path.addCurve(new Point(38,49),new Point(27,68),new Point(38,64));path.closeSubpath();ctx.setFillColor(new Color('203e35'));ctx.addPath(path);ctx.fillPath();ctx.fillRect(new Rect(5,42,17,10));ctx.setFillColor(new Color('5ba46d'));ctx.fillEllipse(new Rect(35,3,20,15));return ctx.getImage();}
  const palette=colour==='ruby'?['f20e22','ffb455']:colour==='magenta'?['b62cde','f0b5ff']:colour==='lilac'?['9251ec','efd5ff']:colour==='neutral'?['c1c5b9','eeeede']:['ff9817','ffe797'];
  if(colour!=='neutral')for(let i=0;i<4;i++){ctx.setFillColor(new Color(palette[0],.02+i*.015));ctx.fillEllipse(new Rect(7+i*8,12+i*8,146-i*16,146-i*16));}
  path.move(new Point(73,18));path.addCurve(new Point(44,73),new Point(77,39),new Point(53,52));path.addCurve(new Point(77,141),new Point(29,106),new Point(45,137));path.addCurve(new Point(126,90),new Point(112,146),new Point(137,117));path.addCurve(new Point(111,60),new Point(122,80),new Point(113,71));path.addCurve(new Point(100,80),new Point(107,68),new Point(108,77));path.addCurve(new Point(73,18),new Point(88,64),new Point(94,39));path.closeSubpath();ctx.setFillColor(new Color(palette[0]));ctx.addPath(path);ctx.fillPath();
  const inner=new Path();inner.move(new Point(81,73));inner.addCurve(new Point(60,116),new Point(78,91),new Point(59,98));inner.addCurve(new Point(81,141),new Point(61,130),new Point(69,140));inner.addCurve(new Point(104,113),new Point(98,141),new Point(107,127));inner.addCurve(new Point(81,73),new Point(101,99),new Point(86,87));inner.closeSubpath();ctx.setFillColor(new Color(palette[1]));ctx.addPath(inner);ctx.fillPath();return ctx.getImage();
 }
 function image(name,assets,fm,colour){
  const path=fm.joinPath(fm.cacheDirectory(),'java-lab-premium-v1-'+name+'.png');
  try{const cached=fm.readImage(path);if(cached)return cached;}catch(_){}
  try{const data=Data.fromBase64String(assets[name]||'');if(data){const img=Image.fromData(data);if(img){try{fm.writeImage(path,img);}catch(_){}return img;}}}catch(_){}
  return nativeFallback(name,colour);
 }
 function addImage(parent,img,width,height){const item=parent.addImage(img);item.imageSize=new Size(width,height);item.applyFittingContentMode();return item;}
 function text(parent,value,size,bold=false){const t=parent.addText(value);t.font=bold?Font.heavySystemFont(size):Font.mediumSystemFont(size);t.textColor=new Color('173f33');t.lineLimit=1;t.minimumScaleFactor=.4;return t;}
 function render(model,assets,fm){
  let compact=false;try{const screen=Device.screenSize();compact=Math.min(screen.width,screen.height)<=320;}catch(_){}
  const medium=model.medium===true,geometry=layout(medium,compact),colour=model.active?tier(model.streak):'neutral';
  const w=new ListWidget();w.setPadding(geometry.padding,medium?15:13,geometry.padding,medium?15:13);w.spacing=0;
  w.backgroundColor=new Color('fbfcf5');const gradient=new LinearGradient();gradient.colors=[new Color('fffef9'),new Color('edf2e7')];gradient.locations=[0,1];gradient.startPoint=new Point(0,0);gradient.endPoint=new Point(1,1);w.backgroundGradient=gradient;
  w.backgroundImage=image(medium?'background-medium':'background-small',assets,fm,colour);
  const header=w.addStack();header.size=new Size(0,geometry.header);header.centerAlignContent();addImage(header,image('logo',assets,fm,colour),13,16);header.addSpacer(5);text(header,'Java Lab',11,true);header.addSpacer();
  w.addSpacer();
  if(medium){const row=w.addStack();row.centerAlignContent();row.addSpacer();addImage(row,image('flame-'+colour,assets,fm,colour),geometry.flame,geometry.flame);row.addSpacer(18);const copy=row.addStack();copy.layoutVertically();copy.size=new Size(140,0);text(copy,String(model.streak),geometry.font,true);text(copy,caption(model.streak),geometry.label);copy.addSpacer(6);const status=text(copy,model.stale?(model.available?'Сохранённый прогресс':'Данных пока нет'):model.isStudy?'Учебный день':'День отдыха',10);status.textColor=new Color('5c7966');const week=text(copy,'Эта неделя · '+model.count+' / 3',9);week.textColor=new Color('768774');row.addSpacer();}
  else{addImage(w,image('flame-'+colour,assets,fm,colour),geometry.flame,geometry.flame).centerAlignImage();const number=text(w,String(model.streak),geometry.font,true);number.centerAlignText();number.minimumScaleFactor=.3;const label=text(w,caption(model.streak),geometry.label);label.centerAlignText();}
  w.addSpacer();return w;
 }
 const api={tier,caption,layout,render};root.LabWidgetUI=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);

const WIDGET_ASSETS={"logo":"","background-small":"","background-medium":"","flame-neutral":"","flame-amber":"","flame-ruby":"","flame-magenta":"","flame-lilac":""};
async function main(){
 const HOME='https://roman-shulpov.github.io/java-backend-lab-site/#home';
 const KEY='java-backend-lab-read-token',BRANCH_KEY='java-backend-lab-branch';
 let medium=config.widgetFamily==='medium',replace=false,diagnostics=false;
 if(!config.runsInWidget&&Keychain.contains(KEY)){
  const menu=new Alert();menu.title='Java Lab';menu.addAction('Маленький виджет');menu.addAction('Средний виджет');menu.addAction('Заменить ключ');menu.addAction('Проверить синхронизацию');menu.addCancelAction('Отмена');
  const choice=await menu.presentAlert();if(choice<0)return;medium=choice===1;replace=choice===2;diagnostics=choice===3;
 }
 if(!config.runsInWidget&&(replace||!Keychain.contains(KEY))){
  const setup=new Alert();setup.title='Java Lab';setup.message='Ключ только для java-backend-lab, Contents: Read-only. Ветка обычно main. Ключ вводится здесь, не в код.';
  setup.addSecureTextField('GitHub token');setup.addTextField('Ветка','main');setup.addAction('Сохранить');setup.addCancelAction('Без подключения');
  if(await setup.presentAlert()>=0){const value=setup.textFieldValue(0).trim();if(value){Keychain.set(KEY,value);Keychain.set(BRANCH_KEY,setup.textFieldValue(1).trim()||'main');}}
 }
 const branch=String(args.widgetParameter||(Keychain.contains(BRANCH_KEY)?Keychain.get(BRANCH_KEY):'main')).trim();
 const fm=FileManager.local(),cache=fm.joinPath(fm.cacheDirectory(),'java-lab-'+encodeURIComponent(branch)+'.json');
 const valid=s=>s&&s.schema===1&&s.entries&&typeof s.entries==='object'&&!Array.isArray(s.entries)&&Array.isArray(s.sessions)&&s.sessions.every(x=>x&&typeof x.date==='string');
 let state=null,stale=false,fetchedAt=null,error='';
 try{
  if(!Keychain.contains(KEY))throw Error('Нужно подключить ключ GitHub в Scriptable.');
  const request=new Request('https://api.github.com/repos/Roman-Shulpov/java-backend-lab/contents/progress/state.json?ref='+encodeURIComponent(branch));
  request.headers={Authorization:'Bearer '+Keychain.get(KEY),Accept:'application/vnd.github.raw+json','X-GitHub-Api-Version':'2022-11-28'};request.timeoutInterval=12;
  const incoming=await request.loadJSON();if(request.response.statusCode!==200||!valid(incoming))throw Error('Не удалось прочитать прогресс. Проверь доступ ключа и ветку.');
  state=incoming;fetchedAt=new Date().toISOString();try{fm.writeString(cache,JSON.stringify({state,fetchedAt}));}catch(_){}
 }catch(e){stale=true;error=e.message||'Нет связи с GitHub.';try{const saved=JSON.parse(fm.readString(cache));if(valid(saved.state)&&Number.isFinite(Date.parse(saved.fetchedAt))){state=saved.state;fetchedAt=saved.fetchedAt;}}catch(_){} }
 // An offline snapshot cannot prove that a scheduled day was missed: freeze its last verified value.
 const cachedDate=stale&&fetchedAt&&Number.isFinite(Date.parse(fetchedAt))?LabRhythm.date(new Date(fetchedAt)):undefined;
 const r=state?LabRhythm.stats(state,cachedDate):{streak:0,active:false,isStudy:false,count:0};
 const widget=LabWidgetUI.render({...r,stale,medium,available:Boolean(state)},WIDGET_ASSETS,fm);
 widget.url=HOME;widget.refreshAfterDate=new Date(Date.now()+15*60*1000);
 Script.setWidget(widget);
 if(!config.runsInWidget){
  if(diagnostics){const info=new Alert();info.title='Синхронизация Java Lab';info.message=(state?(stale?'Последняя сохранённая копия':'Данные получены из GitHub'):'Сохранённых данных пока нет')+'\nВетка: '+branch+'\nСерия: '+r.streak+(fetchedAt?'\nПолучено: '+fetchedAt:'')+(error?'\n'+error:'');info.addAction('Показать виджет');await info.presentAlert();}
  if(medium)await widget.presentMedium();else await widget.presentSmall();
 }
 Script.complete();
}
await main();
